const API = 'https://api.alquran.cloud/v1';
const EDITIONS = { arabic: 'quran-uthmani', turkish: 'tr.yazir' };
const $ = id => document.getElementById(id);
const state = { corpus: null, selected: 1, tab: 'surahs', query: '', favorites: new Set(JSON.parse(localStorage.getItem('quran-favorites') || '[]')), position: JSON.parse(localStorage.getItem('quran-position') || 'null') };
const names = ['Fâtiha','Bakara','Âl-i İmrân','Nisâ','Mâide','En‘âm','A‘râf','Enfâl','Tevbe','Yûnus','Hûd','Yûsuf','Ra‘d','İbrâhîm','Hicr','Nahl','İsrâ','Kehf','Meryem','Tâhâ','Enbiyâ','Hac','Mü’minûn','Nûr','Furkân','Şuarâ','Neml','Kasas','Ankebût','Rûm','Lokmân','Secde','Ahzâb','Sebe’','Fâtır','Yâsîn','Sâffât','Sâd','Zümer','Mü’min','Fussilet','Şûrâ','Zuhruf','Duhân','Câsiye','Ahkâf','Muhammed','Fetih','Hucurât','Kâf','Zâriyât','Tûr','Necm','Kamer','Rahmân','Vâkıa','Hadîd','Mücâdele','Haşr','Mümtehine','Saf','Cum‘a','Münâfikûn','Tegâbün','Talâk','Tahrîm','Mülk','Kalem','Hâkka','Meâric','Nûh','Cin','Müzzemmil','Müddessir','Kıyâme','İnsân','Mürselât','Nebe’','Nâziât','Abese','Tekvîr','İnfitâr','Mutaffifîn','İnşikâk','Bürûc','Târık','A‘lâ','Gâşiye','Fecr','Beled','Şems','Leyl','Duhâ','İnşirâh','Tîn','Alak','Kadr','Beyyine','Zilzâl','Âdiyât','Kâria','Tekâsür','Asr','Hümeze','Fîl','Kureyş','Mâûn','Kevser','Kâfirûn','Nasr','Tebbet','İhlâs','Felak','Nâs'];

function normalize(s) { return String(s).toLocaleLowerCase('tr').normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/ı/g, 'i').replace(/[^a-z0-9\u0600-\u06ff]+/g, ' ').trim(); }
function setStatus(message) { $('status').textContent = message; }
function openDb() { return new Promise((resolve, reject) => { const r = indexedDB.open('kuran-okuma', 1); r.onupgradeneeded = () => r.result.createObjectStore('content'); r.onsuccess = () => resolve(r.result); r.onerror = () => reject(r.error); }); }
async function dbGet(key) { const db = await openDb(); return new Promise((resolve,reject) => { const tx=db.transaction('content'); const r=tx.objectStore('content').get(key); r.onsuccess=()=>resolve(r.result); r.onerror=()=>reject(r.error); tx.oncomplete=()=>db.close(); }); }
async function dbPut(key,value) { const db = await openDb(); return new Promise((resolve,reject) => { const tx=db.transaction('content','readwrite'); tx.objectStore('content').put(value,key); tx.oncomplete=()=>{db.close();resolve();}; tx.onerror=()=>reject(tx.error); }); }
async function fetchEdition(id) { const response=await fetch(`${API}/quran/${id}`, {headers:{Accept:'application/json'}}); if(!response.ok) throw new Error(`Kaynak yanıtı ${response.status}`); const json=await response.json(); if(json.code!==200 || json.data?.edition?.identifier!==id || !Array.isArray(json.data.surahs)) throw new Error('Kaynak sürümü doğrulanamadı'); return json.data; }
function mergeCorpus(ar,tr) { if(ar.surahs.length!==114||tr.surahs.length!==114) throw new Error('114 sure doğrulanamadı'); const surahs=[]; let total=0; for(let i=0;i<114;i++){const a=ar.surahs[i],t=tr.surahs[i]; if(a.number!==i+1||t.number!==i+1||a.ayahs.length!==t.ayahs.length) throw new Error(`${i+1}. sure uyuşmuyor`); const ayahs=[]; for(let j=0;j<a.ayahs.length;j++){const av=a.ayahs[j],tv=t.ayahs[j]; if(av.numberInSurah!==j+1||tv.numberInSurah!==j+1||av.number!==tv.number||!av.text||!tv.text) throw new Error(`${i+1}:${j+1} uyuşmuyor`); ayahs.push({number:j+1,global:av.number,ar:av.text,tr:tv.text}); total++;}surahs.push({number:i+1,name:names[i],arabicName:a.name,count:ayahs.length,ayahs});} if(total!==6236) throw new Error(`Ayet sayısı ${total}; 6236 bekleniyor`); return {surahs,edition:EDITIONS,checkedAt:Date.now()}; }
async function loadCorpus(){try{const stored=await dbGet('corpus-v3-yazir');if(stored?.surahs?.length===114){state.corpus=stored;setStatus('Kayıtlı içerik hazır. Çevrimdışı okuyabilirsiniz.');render();return;}}catch(e){console.warn('Önbellek okunamadı',e);}if(!navigator.onLine){setStatus('İnternet yok. İçerik henüz bu cihaza indirilmemiş.');return;}setStatus('Kur’an metni ve Elmalılı Hamdi Yazır meali ilk kez indiriliyor…');try{const [ar,tr]=await Promise.all([fetchEdition(EDITIONS.arabic),fetchEdition(EDITIONS.turkish)]);const corpus=mergeCorpus(ar,tr);await dbPut('corpus-v3-yazir',corpus);state.corpus=corpus;setStatus('6236 ayet doğrulandı ve çevrimdışı okumak için kaydedildi.');render();}catch(error){console.error(error);setStatus(`İçerik alınamadı: ${error.message}. Bağlantıyı denetleyip yeniden deneyin.`);const button=document.createElement('button');button.className='soft-button';button.textContent='Yeniden dene';button.onclick=loadCorpus;$('status').append(' ',button);}}
function make(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e;}
function ayahKey(s,a){return `${s}:${a}`;}
function renderList(){const list=$('list');list.replaceChildren();let items=[];const query=normalize(state.query);if(state.tab==='favorites'){items=[...state.favorites].map(k=>{const [s,a]=k.split(':').map(Number);return{surah:s,ayah:a};}).filter(x=>state.corpus?.surahs[x.surah-1]?.ayahs[x.ayah-1]);$('count').textContent=`${items.length} favori`;}else if(state.tab==='results'&&query){if(!state.corpus){list.append(make('p','empty','Arama için içerik yükleniyor.'));return;}for(const surah of state.corpus.surahs){if(normalize(surah.name).includes(query)||String(surah.number)===query)items.push({surah:surah.number});for(const ayah of surah.ayahs){if(normalize(ayah.tr).includes(query)||normalize(ayah.ar).includes(query)||ayahKey(surah.number,ayah.number)===query) items.push({surah:surah.number,ayah:ayah.number});if(items.length>=200)break;}if(items.length>=200)break;}$('count').textContent=items.length===200?'İlk 200 sonuç':`${items.length} sonuç`;}else{items=Array.from({length:114},(_,i)=>({surah:i+1})).filter(x=>!query||normalize(names[x.surah-1]).includes(query)||String(x.surah)===query);$('count').textContent=`${items.length} sure`;}if(!items.length){list.append(make('p','empty',state.tab==='favorites'?'Henüz favori ayet yok. Ayetin yanındaki yıldızı kullanın.':'Sonuç bulunamadı.'));return;}const frag=document.createDocumentFragment();for(const item of items){const s=item.surah,a=item.ayah;const button=make('button','surah-item'+(s===state.selected&&!a?' active':''));button.type='button';button.dataset.surah=s;if(a)button.dataset.ayah=a;button.append(make('span','number',a?String(a):String(s)));const text=make('span','');text.append(make('span','surah-name',names[s-1]+(a?` · ${s}:${a}`:'')));let sub=state.corpus?.surahs[s-1]?.count; text.append(make('span','surah-sub',a?state.corpus.surahs[s-1].ayahs[a-1].tr.slice(0,65):sub?`${sub} ayet`:'Sure'));button.append(text);if(!a&&state.corpus)button.append(make('span','surah-arabic',state.corpus.surahs[s-1].arabicName));frag.append(button);}list.append(frag);}
function renderReader(targetAyah){const area=$('verses');area.replaceChildren();const s=state.corpus?.surahs[state.selected-1];if(!s)return;$('surah-title').textContent=`${s.number}. ${s.name} Suresi`;$('surah-meta').textContent=`${s.count} ayet · ${s.arabicName}`;$('resume').hidden=!state.position;const frag=document.createDocumentFragment();for(const ayah of s.ayahs){const key=ayahKey(s.number,ayah.number);const card=make('article','verse');card.id=`ayet-${ayah.number}`;const head=make('div','verse-heading');head.append(make('span','',key));const actions=make('span','verse-actions');const save=make('button','','⌑');save.type='button';save.title='Burayı kaldığım yer olarak kaydet';save.setAttribute('aria-label',`${key} ayetini kaldığım yer olarak kaydet`);save.dataset.save=key;const fav=make('button','',state.favorites.has(key)?'★':'☆');fav.type='button';fav.title='Favori';fav.dataset.favorite=key;fav.setAttribute('aria-label',`${key} ayetini favorilere ekle veya çıkar`);fav.setAttribute('aria-pressed',state.favorites.has(key));actions.append(save,fav);head.append(actions);card.append(head,make('p','arabic',ayah.ar),make('p','translation',ayah.tr));frag.append(card);}area.append(frag);if(targetAyah)requestAnimationFrame(()=>document.getElementById(`ayet-${targetAyah}`)?.scrollIntoView({behavior:'smooth',block:'start'}));}
function render(targetAyah){renderList();renderReader(targetAyah);}
function selectSurah(s,a){state.selected=s;render(a);if(innerWidth<801)document.querySelector('.reader').scrollIntoView({behavior:'smooth'});}
function savePosition(key){const [surah,ayah]=key.split(':').map(Number);state.position={surah,ayah};localStorage.setItem('quran-position',JSON.stringify(state.position));$('resume').hidden=false;setStatus(`Kaldığınız yer ${key} olarak kaydedildi.`);}
function bind(){const theme=localStorage.getItem('quran-theme')||'light';document.documentElement.classList.toggle('dark',theme==='dark');$('theme').setAttribute('aria-label',theme==='dark'?'Açık temaya geç':'Koyu temaya geç');$('theme').onclick=()=>{const dark=document.documentElement.classList.toggle('dark');localStorage.setItem('quran-theme',dark?'dark':'light');$('theme').setAttribute('aria-label',dark?'Açık temaya geç':'Koyu temaya geç');};$('info').onclick=()=>$('source-dialog').showModal();$('close-info').onclick=()=>$('source-dialog').close();$('source-dialog').onclick=e=>{if(e.target===$('source-dialog'))e.target.close();};$('search').oninput=e=>{state.query=e.target.value;state.tab=state.query?'results':'surahs';document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.dataset.tab===state.tab));renderList();};document.querySelectorAll('.tab').forEach(tab=>tab.onclick=()=>{state.tab=tab.dataset.tab;document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x===tab));renderList();});$('list').onclick=e=>{const item=e.target.closest('[data-surah]');if(item)selectSurah(Number(item.dataset.surah),item.dataset.ayah?Number(item.dataset.ayah):null);};$('verses').onclick=e=>{const fav=e.target.closest('[data-favorite]');if(fav){const key=fav.dataset.favorite;state.favorites.has(key)?state.favorites.delete(key):state.favorites.add(key);localStorage.setItem('quran-favorites',JSON.stringify([...state.favorites]));fav.textContent=state.favorites.has(key)?'★':'☆';fav.setAttribute('aria-pressed',state.favorites.has(key));if(state.tab==='favorites')renderList();return;}const save=e.target.closest('[data-save]');if(save)savePosition(save.dataset.save);};$('resume').onclick=()=>{if(state.position)selectSurah(state.position.surah,state.position.ayah);};const network=()=>{$('offline-indicator').textContent=navigator.onLine?'Çevrimiçi':'Çevrimdışı';};window.addEventListener('online',network);window.addEventListener('offline',network);network();}
bind();renderList();loadCorpus();if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(console.warn);

const appState={location:null,prayers:null,tomorrow:null,qibla:null,heading:null,aligned:false};
const prayerMap=[['Fajr','İmsak'],['Sunrise','Güneş'],['Dhuhr','Öğle'],['Asr','İkindi'],['Maghrib','Akşam'],['Isha','Yatsı']];
function showPage(name){document.querySelectorAll('.page').forEach(p=>p.classList.toggle('active',p.id===`page-${name}`));document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.pageTarget===name));scrollTo({top:0,behavior:'smooth'});if(name==='qibla')updateQiblaView();if(name==='duas')renderDuas();}
document.querySelectorAll('[data-page-target]').forEach(button=>button.addEventListener('click',()=>showPage(button.dataset.pageTarget)));
function dateKey(date){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;}
function cleanTime(value){return String(value||'').match(/^\d{2}:\d{2}/)?.[0]||null;}
function timeOn(date,time){const [h,m]=time.split(':').map(Number);const result=new Date(date);result.setHours(h,m,0,0);return result;}
async function fetchPrayerDay(date,coords){const key=`prayers:${dateKey(date)}:${coords.latitude.toFixed(2)}:${coords.longitude.toFixed(2)}`;const cached=JSON.parse(localStorage.getItem(key)||'null');if(cached)return cached;const stamp=Math.floor(new Date(date.getFullYear(),date.getMonth(),date.getDate(),12).getTime()/1000);const url=`https://api.aladhan.com/v1/timings/${stamp}?latitude=${encodeURIComponent(coords.latitude)}&longitude=${encodeURIComponent(coords.longitude)}&method=13&school=1`;
 const response=await fetch(url);if(!response.ok)throw new Error(`Vakit kaynağı ${response.status}`);const json=await response.json();if(json.code!==200)throw new Error('Vakit verisi doğrulanamadı');const timings={};for(const [key] of prayerMap){const value=cleanTime(json.data.timings[key]);if(!value)throw new Error(`${key} vakti eksik`);timings[key]=value;}const value={timings,date:dateKey(date),timezone:json.data.meta?.timezone||'',method:json.data.meta?.method?.name||'Türkiye'};localStorage.setItem(key,JSON.stringify(value));return value;}
async function loadPrayerTimes(coords){$('prayer-status').textContent='Güncel vakitler alınıyor…';try{const today=new Date(),tomorrow=new Date(today);tomorrow.setDate(today.getDate()+1);[appState.prayers,appState.tomorrow]=await Promise.all([fetchPrayerDay(today,coords),fetchPrayerDay(tomorrow,coords)]);$('location-label').textContent=`Konum ${coords.latitude.toFixed(3)}, ${coords.longitude.toFixed(3)} · Türkiye hesaplama yöntemi`;renderPrayerTimes();}catch(error){const saved=Object.keys(localStorage).find(k=>k.startsWith(`prayers:${dateKey(new Date())}:`));if(saved){appState.prayers=JSON.parse(localStorage.getItem(saved));$('prayer-status').textContent='İnternet yok; bugün için kayıtlı vakitler gösteriliyor.';renderPrayerTimes();}else $('prayer-status').textContent=`Vakitler alınamadı: ${error.message}`;}}
function getNextPrayer(){if(!appState.prayers)return null;const now=new Date();for(const [key,label] of prayerMap){if(key==='Sunrise')continue;const at=timeOn(now,appState.prayers.timings[key]);if(at>now)return{key,label,at,time:appState.prayers.timings[key]};}if(appState.tomorrow){const next=new Date(now);next.setDate(now.getDate()+1);return{key:'Fajr',label:'İmsak',at:timeOn(next,appState.tomorrow.timings.Fajr),time:appState.tomorrow.timings.Fajr};}return null;}
function renderPrayerTimes(){if(!appState.prayers)return;const next=getNextPrayer(),grid=$('prayer-grid');grid.replaceChildren();for(const [key,label] of prayerMap){const card=make('div','prayer-time'+(next?.key===key?' next':''));card.append(make('span','',label),make('strong','',appState.prayers.timings[key]));grid.append(card);}$('prayer-status').textContent='AlAdhan Türkiye/Diyanet yöntemi · Yerel takvimle birkaç dakika fark olabilir.';updateCountdown();}
function updateCountdown(){const next=getNextPrayer();if(!next)return;$('next-prayer-name').textContent=next.label;$('next-prayer-time').textContent=`Saat ${next.time}`;const mins=Math.max(0,Math.ceil((next.at-Date.now())/60000));$('countdown').textContent=mins>=60?`${Math.floor(mins/60)} sa ${mins%60} dk`:`${mins} dk`;document.querySelectorAll('.prayer-time').forEach(card=>card.classList.toggle('next',card.firstChild?.textContent===next.label));}
function requestLocation(){if(!navigator.geolocation){$('prayer-status').textContent='Bu cihaz konum özelliğini desteklemiyor.';return;}navigator.geolocation.getCurrentPosition(pos=>{appState.location={latitude:pos.coords.latitude,longitude:pos.coords.longitude,accuracy:pos.coords.accuracy};localStorage.setItem('last-location',JSON.stringify(appState.location));appState.qibla=qiblaBearing(appState.location.latitude,appState.location.longitude);loadPrayerTimes(appState.location);updateQiblaView();},error=>{$('prayer-status').textContent=error.code===1?'Konum izni verilmedi. Vakitler ve kıble için izni açıp yeniden deneyin.':'Konum alınamadı. GPS’i açıp yeniden deneyin.';},{enableHighAccuracy:true,timeout:15000,maximumAge:3600000});}
function qiblaBearing(lat,lon){const φ=Math.PI*lat/180,φK=Math.PI*21.4225/180,Δ=Math.PI*(39.8262-lon)/180;return(Math.atan2(Math.sin(Δ),Math.cos(φ)*Math.tan(φK)-Math.sin(φ)*Math.cos(Δ))*180/Math.PI+360)%360;}
function angleError(target,heading){return((target-heading+540)%360)-180;}
function updateQiblaView(){if(!appState.location){$('qibla-degree').textContent='Konum bekleniyor';$('qibla-instruction').textContent='Konum izni vererek Kâbe yönünü hesaplayın.';return;}appState.qibla=qiblaBearing(appState.location.latitude,appState.location.longitude);$('qibla-degree').textContent=`Kıble: ${Math.round(appState.qibla)}°`;if(appState.heading==null){$('qibla-arrow').style.transform=`translateX(-50%) rotate(${appState.qibla}deg)`;$('qibla-instruction').textContent='Pusulayı başlatın; ok Kâbe yönünü gösterecek.';return;}const error=angleError(appState.qibla,appState.heading),aligned=Math.abs(error)<=5;$('qibla-arrow').style.transform=`translateX(-50%) rotate(${error}deg)`;$('qibla-arrow').style.color=aligned?'#19965f':'#c4473b';$('qibla-instruction').textContent=aligned?'Kıbleye hizalandınız.':`${error>0?'Sağa':'Sola'} ${Math.round(Math.abs(error))}° dönün.`;if(aligned&&!appState.aligned&&navigator.vibrate)navigator.vibrate(80);appState.aligned=aligned;}
function orientationHandler(event){let heading=event.webkitCompassHeading;if(typeof heading!=='number'&&typeof event.alpha==='number')heading=(360-event.alpha)%360;if(typeof heading==='number'){appState.heading=heading;updateQiblaView();}}
async function startCompass(){try{if(typeof DeviceOrientationEvent!=='undefined'&&typeof DeviceOrientationEvent.requestPermission==='function'){const result=await DeviceOrientationEvent.requestPermission();if(result!=='granted')throw new Error('Pusula izni verilmedi');}window.removeEventListener('deviceorientationabsolute',orientationHandler);window.removeEventListener('deviceorientation',orientationHandler);window.addEventListener('deviceorientationabsolute',orientationHandler,true);window.addEventListener('deviceorientation',orientationHandler,true);$('start-compass').textContent='Pusula açık';$('qibla-instruction').textContent='Telefonu düz tutup yavaşça döndürün.';}catch(error){$('qibla-instruction').textContent=error.message;}}
const duas=[{title:'Hz. Yûnus’un duası',surah:21,from:87,to:87},{title:'Hz. Mûsâ’nın duası',surah:20,from:25,to:28},{title:'Hz. Mûsâ’nın hayır duası',surah:28,from:24,to:24},{title:'Hz. İbrâhim’in namaz duası',surah:14,from:40,to:41},{title:'Hz. Nûh’un duası',surah:71,from:28,to:28}];
function renderDuas(){const list=$('dua-list');if(!state.corpus){list.innerHTML='<div class="status">Kur’an içeriği hazırlanıyor…</div>';return;}list.replaceChildren();for(const dua of duas){const surah=state.corpus.surahs[dua.surah-1],verses=surah.ayahs.slice(dua.from-1,dua.to);const card=make('article','dua-card');card.append(make('span','dua-reference',`${surah.name} ${dua.surah}:${dua.from}${dua.to>dua.from?`–${dua.to}`:''}`),make('h2','',dua.title),make('p','dua-arabic',verses.map(v=>v.ar).join(' ۞ ')),make('p','dua-translation',verses.map(v=>v.tr).join(' ')));list.append(card);}}
$('refresh-location').addEventListener('click',requestLocation);$('start-compass').addEventListener('click',startCompass);$('today-label').textContent=new Intl.DateTimeFormat('tr-TR',{weekday:'long',day:'numeric',month:'long'}).format(new Date());setInterval(updateCountdown,30000);const lastLocation=JSON.parse(localStorage.getItem('last-location')||'null');if(lastLocation){appState.location=lastLocation;appState.qibla=qiblaBearing(lastLocation.latitude,lastLocation.longitude);loadPrayerTimes(lastLocation);}else requestLocation();const duaTimer=setInterval(()=>{if(state.corpus){clearInterval(duaTimer);renderDuas();}},300);

state.selected=null;
const nativeIslam=()=>window.Capacitor?.Plugins?.IslamNative;
const baseRenderReader=renderReader;
renderReader=function(targetAyah){if(!state.selected){$('verses').replaceChildren(make('div','empty-reader','Başlamak için listeden bir sure seçin.'));$('surah-title').textContent='Bir sure seçin';$('surah-meta').textContent='Listeden okumak veya dinlemek istediğiniz sureye dokunun.';$('resume').hidden=!state.position;$('audio-panel').hidden=true;return;}baseRenderReader(targetAyah);const s=state.corpus?.surahs[state.selected-1];if(!s)return;const url=`https://cdn.islamic.network/quran/audio-surah/128/ar.alafasy/${s.number}.mp3`;$('audio-panel').hidden=false;$('download-arabic').href=url;$('download-arabic').setAttribute('download',`${s.number}-${s.name}-arapca.mp3`);};
renderReader();
function selectedSurah(){return state.selected&&state.corpus?.surahs[state.selected-1];}
$('play-arabic').onclick=()=>{const s=selectedSurah();if(!s)return;const player=$('quran-audio');player.src=`https://cdn.islamic.network/quran/audio-surah/128/ar.alafasy/${s.number}.mp3`;player.hidden=false;player.play().catch(()=>setStatus('Ses başlatılamadı. Bağlantıyı denetleyin.'));};
$('play-turkish').onclick=async()=>{const s=selectedSurah();if(!s)return;let i=0;const player=$('quran-audio');player.hidden=false;const next=()=>{if(i>=s.ayahs.length)return;player.src=`https://cdn.islamic.network/quran/audio/128/tr.vakfi-audio/${s.ayahs[i++].global}.mp3`;player.play().catch(()=>setStatus('Türkçe ses başlatılamadı. Önce “Türkçe indir” ile kaydedebilirsiniz.'));};player.onended=next;next();setStatus(`${s.name} suresinin Türkçe Vakfı meali dinletiliyor.`);};
$('download-turkish').onclick=async()=>{const s=selectedSurah();if(!s)return;const b=$('download-turkish');b.disabled=true;try{const cache=await caches.open('turkish-audio-v1');let done=0;for(const a of s.ayahs){const url=`https://cdn.islamic.network/quran/audio/128/tr.vakfi-audio/${a.global}.mp3`;if(!await cache.match(url))await cache.add(url);done++;b.textContent=`İndiriliyor ${done}/${s.count}`;}setStatus(`${s.name} suresinin Türkçe sesleri çevrimdışı dinlemek için kaydedildi.`);}catch(e){setStatus('Türkçe ses indirilemedi. İnternet bağlantısını denetleyin.');}finally{b.disabled=false;b.textContent='↓ Türkçe indir';}};

requestLocation=async function(){$('prayer-status').textContent='Konum izni bekleniyor…';try{let c;if(nativeIslam()?.getLocation)c=await nativeIslam().getLocation();else c=await new Promise((ok,no)=>navigator.geolocation?.getCurrentPosition(p=>ok({latitude:p.coords.latitude,longitude:p.coords.longitude,accuracy:p.coords.accuracy}),no,{enableHighAccuracy:true,timeout:20000,maximumAge:300000})||no(new Error('Konum desteklenmiyor')));appState.location={latitude:Number(c.latitude),longitude:Number(c.longitude),accuracy:Number(c.accuracy||0)};localStorage.setItem('last-location',JSON.stringify(appState.location));appState.qibla=qiblaBearing(appState.location.latitude,appState.location.longitude);await loadPrayerTimes(appState.location);updateQiblaView();}catch(e){$('prayer-status').textContent='Konum alınamadı. Telefon ayarlarından İslam Rehberi için konum iznini ve GPS’i açıp yeniden deneyin.';console.warn(e);}};
$('refresh-location').onclick=requestLocation;

duas.push({title:'Hz. Âdem ile Havvâ’nın tövbe duası',surah:7,from:23,to:23},{title:'Hz. Eyyûb’un şifa duası',surah:21,from:83,to:83},{title:'Hz. Zekeriyyâ’nın evlat duası',surah:21,from:89,to:89},{title:'Hz. Yûsuf’un teslimiyet duası',surah:12,from:101,to:101},{title:'Hz. Lût’un yardım duası',surah:29,from:30,to:30},{title:'Hz. Süleyman’ın şükür duası',surah:27,from:19,to:19},{title:'Hz. İbrâhim’in güvenlik duası',surah:14,from:35,to:35});
const hadiths=[{text:'Ameller niyetlere göredir. Herkese ancak niyet ettiği vardır.',narrator:'Hz. Ömer’den rivayet edilmiştir.',source:'Buhârî, Bed’ü’l-vahy, 1'},{text:'Sizin en hayırlınız Kur’an’ı öğrenen ve öğretendir.',narrator:'Hz. Osman’dan rivayet edilmiştir.',source:'Buhârî, Fezâilü’l-Kur’ân, 21'},{text:'Müslüman, elinden ve dilinden Müslümanların güvende olduğu kimsedir.',narrator:'Abdullah b. Amr’dan rivayet edilmiştir.',source:'Buhârî, Îmân, 4'},{text:'Kolaylaştırın, zorlaştırmayın; müjdeleyin, nefret ettirmeyin.',narrator:'Enes b. Mâlik’ten rivayet edilmiştir.',source:'Buhârî, İlim, 11'},{text:'Merhamet etmeyene merhamet olunmaz.',narrator:'Cerîr b. Abdullah’tan rivayet edilmiştir.',source:'Buhârî, Edeb, 18'},{text:'Sizden biri kendisi için istediğini kardeşi için de istemedikçe iman etmiş olmaz.',narrator:'Enes b. Mâlik’ten rivayet edilmiştir.',source:'Buhârî, Îmân, 7'},{text:'Allah sizin suretlerinize ve mallarınıza bakmaz; kalplerinize ve amellerinize bakar.',narrator:'Ebû Hüreyre’den rivayet edilmiştir.',source:'Müslim, Birr, 34'},{text:'Temizlik imanın yarısıdır.',narrator:'Ebû Mâlik el-Eş’arî’den rivayet edilmiştir.',source:'Müslim, Tahâret, 1'}];
let guideKind='dua';const baseRenderDuas=renderDuas;renderDuas=function(){if(guideKind==='dua'){baseRenderDuas();return;}const list=$('dua-list');list.replaceChildren();for(const h of hadiths){const card=make('article','dua-card hadith-card');card.append(make('span','dua-reference',h.source),make('p','hadith-text',`“${h.text}”`),make('p','hadith-narrator',h.narrator));list.append(card);}};
document.querySelectorAll('[data-content]').forEach(b=>b.onclick=()=>{guideKind=b.dataset.content;document.querySelectorAll('[data-content]').forEach(x=>x.classList.toggle('active',x===b));renderDuas();});

const notifyBox=document.createElement('section');notifyBox.className='notification-settings';notifyBox.innerHTML='<div><span class="eyebrow">BİLDİRİM ÇUBUĞU</span><h2>Vakitleri sürekli görün</h2><p>Android bildiriminde gösterilecek bilgiyi seçin.</p></div><label class="notify-control"><input id="notify-enabled" type="checkbox"> Bildirimi aç</label><select id="notify-mode"><option value="next">Yalnızca en yakın vakit</option><option value="all">Tüm vakitler ve en yakın vakit</option></select>';$('prayer-grid').after(notifyBox);
const ne=$('notify-enabled'),nm=$('notify-mode');ne.checked=localStorage.getItem('prayer-notify')==='1';nm.value=localStorage.getItem('prayer-notify-mode')||'next';async function syncPrayerNotification(){if(!nativeIslam()?.setPrayerNotification)return;if(!ne.checked){await nativeIslam().stopPrayerNotification();return;}if(!appState.prayers)return;const n=getNextPrayer();await nativeIslam().setPrayerNotification({mode:nm.value,nextName:n.label,nextTime:n.time,nextAt:n.at.getTime(),times:prayerMap.map(([k,l])=>`${l} ${appState.prayers.timings[k]}`).join(' · ')});}ne.onchange=()=>{localStorage.setItem('prayer-notify',ne.checked?'1':'0');syncPrayerNotification().catch(console.warn);};nm.onchange=()=>{localStorage.setItem('prayer-notify-mode',nm.value);syncPrayerNotification().catch(console.warn);};const baseRenderPrayerTimes=renderPrayerTimes;renderPrayerTimes=function(){baseRenderPrayerTimes();syncPrayerNotification().catch(console.warn);};requestLocation();
